/// Local time, `HH:MM:SS`.
typedef TimeString = String;

/// A client for the Catalog API. [baseUrl] is required: read it from the
/// environment, never hard-code a server.
class CatalogClient {
  CatalogClient({
    required String baseUrl,
    http.Client? httpClient,
    String? clientName,
  }) : _api = ApiClient(
          baseUrl: baseUrl,
          httpClient: httpClient,
          clientName: clientName,
        );

  final ApiClient _api;

  /// Closes the underlying HTTP client if this client created it.
  void close() => _api.close();

  /// Terms with sections on offer
  ///
  /// Every term that has at least one section that is not cancelled, newest first, with its parts of term.
  /// `dropAddEnds` is the last day to add or drop a class in the term's longest part of term.
  Future<TermList> listTerms() async {
    final json = await _api.send('GET', '/terms', query: const {});
    return TermList.fromJson(json as Map<String, dynamic>);
  }

  /// Subjects
  ///
  /// Every subject, ordered by abbreviation. With `term`, only the subjects that have a course with a section
  /// on offer that term, and `courseCount` counts those courses; without it, `courseCount` counts every
  /// course the catalog has ever seen in the subject.
  Future<SubjectList> listSubjects({TermCode? term}) async {
    final json = await _api.send('GET', '/subjects', query: {
        if (term != null) 'term': term.toString(),
      });
    return SubjectList.fromJson(json as Map<String, dynamic>);
  }

  /// Courses in a subject that are offered in a term
  ///
  /// Ordered by course number.
  Future<SubjectCourses> listSubjectCourses({required String abbr, required TermCode term}) async {
    final json = await _api.send('GET', '/subjects/${Uri.encodeComponent(abbr.toString())}/courses', query: {
        'term': term.toString(),
      });
    return SubjectCourses.fromJson(json as Map<String, dynamic>);
  }

  /// Search courses offered in a term
  ///
  /// Full-text search over course codes and titles (Postgres `websearch_to_tsquery`, so quoted phrases, `or`
  /// and `-exclusion` work). A code matches with or without its space: `csci1301` and `csci 1301` both find
  /// `CSCI1301`. Results are
  /// courses with at least one section on offer in the term, exact code matches first.
  Future<SearchResults> searchCourses({required TermCode term, required String q, int? limit}) async {
    final json = await _api.send('GET', '/search', query: {
        'term': term.toString(),
        'q': q.toString(),
        if (limit != null) 'limit': limit.toString(),
      });
    return SearchResults.fromJson(json as Map<String, dynamic>);
  }

  /// One course
  ///
  /// The course, its Bulletin details when the catalog has them, and every term it has a section on offer.
  /// The code is matched without regard to case, spaces or hyphens: `csci%201301` and `csci-1301` find
  /// `CSCI1301`.
  Future<CourseDetail> getCourse({required String abbr, TermCode? term}) async {
    final json = await _api.send('GET', '/courses/${Uri.encodeComponent(abbr.toString())}', query: {
        if (term != null) 'term': term.toString(),
      });
    return CourseDetail.fromJson(json as Map<String, dynamic>);
  }

  /// Whether a course exists
  ///
  /// A cheap check for imports and links. Always `200`: `exists` is false for a code the catalog has never
  /// seen. With `term`, `offered` says whether the course has a section on offer that term.
  Future<CourseExists> courseExists({required String abbr, TermCode? term}) async {
    final json = await _api.send('GET', '/course-exists', query: {
        'abbr': abbr.toString(),
        if (term != null) 'term': term.toString(),
      });
    return CourseExists.fromJson(json as Map<String, dynamic>);
  }

  /// Sections of several courses in a term
  ///
  /// Every section of the given courses in the term, cancelled ones included (check `cancelled`), each with
  /// its meetings. Name the courses by code (`courses`), by id (`courseIds`), or both; together they may not
  /// exceed 15. A code the catalog does not know is skipped, not an error.
  Future<SectionList> listSections({required TermCode term, String? courses, String? courseIds}) async {
    final json = await _api.send('GET', '/sections', query: {
        'term': term.toString(),
        if (courses != null) 'courses': courses.toString(),
        if (courseIds != null) 'courseIds': courseIds.toString(),
      });
    return SectionList.fromJson(json as Map<String, dynamic>);
  }
}
